WITH latest AS (SELECT id, store_name, opened_date FROM stores QUALIFY RANK() OVER (PARTITION BY city ORDER BY opened_date) = 1), kept AS (SELECT s.* FROM latest s WHERE EXISTS (SELECT 1 FROM orders c WHERE c.store_id = s.id AND c.status NOT IN ('CANCELLED', 'PENDING'))), enriched AS (SELECT id, store_name, ROW_NUMBER() OVER w_ordered AS event_seq, ROW_NUMBER() OVER w_ordered AS seq_no, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('YEAR', opened_date) ORDER BY opened_date DESC, id) AS seq_no_2 FROM kept WINDOW w_ordered AS (ORDER BY opened_date DESC, id)), latest_match AS (SELECT s.id, s.store_name, s.seq_no, s.seq_no_2, top1.order_discount, top1.order_shipping_fee FROM enriched s LEFT JOIN LATERAL (SELECT c.discount AS order_discount, c.shipping_fee AS order_shipping_fee FROM orders c WHERE c.store_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) top1 ON TRUE), kept_stores AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM orders ch WHERE ch.store_id = s.id AND ch.discount IS NOT NULL)), stats AS (SELECT seq_no, SUM(order_shipping_fee) AS total_order_shipping_fee, APPROX_PERCENTILE(seq_no_2, 0.9) AS seq_no_2_p90, AVG(seq_no_2) AS avg_seq_no_2, AVG(order_discount) AS avg_order_discount, COUNT(*) AS num_rows FROM kept_stores GROUP BY seq_no) SELECT seq_no, total_order_shipping_fee, seq_no_2_p90, avg_order_discount, num_rows FROM stats
